     5	/** Nơi lưu trữ đơn hàng. Có thể thay bằng database thật mà không đổi order-service. */
     6	export interface OrderRepository {
     7	  findAll(): Promise<Order[]>;
     8	  findById(id: string): Promise<Order | null>;
     9	  /** Thêm mới hoặc cập nhật (theo id). */
    10	  save(order: Order): Promise<void>;
    11	}
    12	
    13	export const DEFAULT_ORDERS_FILE = path.join(process.cwd(), "storage", "orders.json");
    14	
    15	/** Lưu đơn hàng vào một file JSON - đủ dùng cho môi trường học tập, không dùng cho production. */
    16	export function createJsonFileOrderRepository(filePath: string): OrderRepository {
    17	  async function readAll(): Promise<Order[]> {
    18	    try {
    19	      const raw = await fs.readFile(filePath, "utf8");
    20	      const data: unknown = JSON.parse(raw);
    21	      return Array.isArray(data) ? (data as Order[]) : [];
    22	    } catch (error) {
    23	      if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    24	      throw error;
    25	    }
    26	  }
    27	
    28	  async function writeAll(orders: Order[]): Promise<void> {
    29	    await fs.mkdir(path.dirname(filePath), { recursive: true });
    30	    const tempFile = `${filePath}.tmp`;
    31	    await fs.writeFile(tempFile, JSON.stringify(orders, null, 2), "utf8");
    32	    await fs.rename(tempFile, filePath);
    33	  }
    34	
    35	  return {
    36	    findAll: readAll,
    37	
    38	    async findById(id) {
    39	      const orders = await readAll();
    40	      return orders.find((order) => order.id === id) ?? null;
    41	    },
    42	
    43	    async save(order) {
    44	      const orders = await readAll();
    45	      const index = orders.findIndex((item) => item.id === order.id);
    46	      if (index >= 0) {
    47	        orders[index] = order;
    48	      } else {
    49	        orders.push(order);
    50	      }
    51	      await writeAll(orders);
    52	    },
    53	  };
    54	}
    55	
    56	/** Repository trong bộ nhớ - dùng cho unit test. */
    57	export function createInMemoryOrderRepository(seed: Order[] = []): OrderRepository {
    58	  const orders = new Map(seed.map((order) => [order.id, structuredClone(order)]));
    59	
    60	  return {
    61	    async findAll() {
    62	      return [...orders.values()].map((order) => structuredClone(order));
    63	    },
    64	    async findById(id) {
    65	      const order = orders.get(id);
    66	      return order ? structuredClone(order) : null;
    67	    },
    68	    async save(order) {
    69	      orders.set(order.id, structuredClone(order));
    70	    },
    71	  };
