     6	export const SHIPPING_METHODS = ["standard", "express"] as const;
     7	
     8	export type ShippingMethod = (typeof SHIPPING_METHODS)[number];
     9	
    10	export const SHIPPING_OPTIONS: Record<
    11	  ShippingMethod,
    12	  { label: string; description: string; fee: number }
    13	> = {
    14	  standard: { label: "Giao hàng tiêu chuẩn", description: "3–5 ngày làm việc", fee: 30_000 },
    15	  express: { label: "Giao hàng nhanh", description: "1–2 ngày làm việc", fee: 60_000 },
    16	};
    17	
    18	/** Đơn từ mức này trở lên được miễn phí giao hàng tiêu chuẩn. */
    19	export const FREE_SHIPPING_THRESHOLD = 500_000;
    20	
    21	export interface PriceLine {
    22	  unitPrice: number;
    23	  quantity: number;
    24	}
    25	
    26	export interface OrderTotals {
    27	  subtotal: number;
    28	  shippingFee: number;
    29	  total: number;
    30	}
    31	
    32	export function calculateSubtotal(lines: PriceLine[]): number {
    33	  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0);
    34	}
    35	
    36	export function calculateShippingFee(subtotal: number, method: ShippingMethod): number {
    37	  if (subtotal <= 0) return 0;
    38	  if (method === "standard" && subtotal >= FREE_SHIPPING_THRESHOLD) return 0;
    39	  return SHIPPING_OPTIONS[method].fee;
    40	}
    41	
    42	export function calculateOrderTotals(lines: PriceLine[], method: ShippingMethod): OrderTotals {
    43	  const subtotal = calculateSubtotal(lines);
    44	  const shippingFee = calculateShippingFee(subtotal, method);
    45	  return { subtotal, shippingFee, total: subtotal + shippingFee };
    46	}
    47	
    48	/** Số tiền cần mua thêm để được miễn phí giao hàng tiêu chuẩn. */
    49	export function amountUntilFreeShipping(subtotal: number): number {
    50	  return Math.max(0, FREE_SHIPPING_THRESHOLD - subtotal);
    51	}

