import { createHmac, timingSafeEqual } from "node:crypto";

export const STAFF_COOKIE = "sl_staff";
export const STAFF_SESSION_SECONDS = 12 * 60 * 60;

export interface StaffSession {
  username: string;
  /** Thời điểm hết hạn, tính bằng mili giây epoch. */
  exp: number;
}

const sign = (data: string, secret: string) =>
  createHmac("sha256", secret).update(data).digest("base64url");

/** Tạo token dạng base64url(payload).base64url(HMAC-SHA256). */
export function signSession(session: StaffSession, secret: string): string {
  const payload = Buffer.from(JSON.stringify(session)).toString("base64url");
  return `${payload}.${sign(payload, secret)}`;
}

/** Trả về phiên nếu token đúng chữ ký, đúng định dạng và chưa hết hạn; ngược lại null. */
export function verifySession(token: string, secret: string, now: number): StaffSession | null {
  if (!secret) return null;
  const parts = token.split(".");
  if (parts.length !== 2) return null;
  const [payload, signature] = parts;

  const expected = Buffer.from(sign(payload, secret));
  const actual = Buffer.from(signature);
  if (expected.length !== actual.length || !timingSafeEqual(expected, actual)) return null;

  try {
    const data: unknown = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
    if (typeof data !== "object" || data === null) return null;
    const { username, exp } = data as Record<string, unknown>;
    if (typeof username !== "string" || !username) return null;
    if (typeof exp !== "number" || !Number.isFinite(exp) || exp <= now) return null;
    return { username, exp };
  } catch {
    return null;
  }
}
import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";
import { z } from "zod";

const KEY_LENGTH = 64;

export interface StaffAccount {
  username: string;
  displayName: string;
  passwordHash: string;
}

/** Băm mật khẩu: `scrypt$<saltHex>$<hashHex>`. */
export function hashPassword(password: string, salt: Buffer = randomBytes(16)): string {
  const hash = scryptSync(password, salt, KEY_LENGTH);
  return `scrypt$${salt.toString("hex")}$${hash.toString("hex")}`;
}

export function verifyPassword(password: string, stored: string): boolean {
  const [scheme, saltHex, hashHex, ...rest] = stored.split("$");
  if (scheme !== "scrypt" || !saltHex || !hashHex || rest.length > 0) return false;
  if (!/^[0-9a-f]+$/i.test(saltHex) || !/^[0-9a-f]+$/i.test(hashHex)) return false;
  const expected = Buffer.from(hashHex, "hex");
  if (expected.length !== KEY_LENGTH) return false;
  const actual = scryptSync(password, Buffer.from(saltHex, "hex"), KEY_LENGTH);
  return timingSafeEqual(actual, expected);
}

const accountsSchema = z
  .array(
    z.object({
      username: z.string().min(1),
      displayName: z.string().min(1),
      passwordHash: z.string().min(1),
    }),
  )
  .min(1);

export type ParsedStaffAccounts =
  { accounts: StaffAccount[]; reason?: undefined } | { accounts: null; reason: string };

/** Đọc JSON `STAFF_ACCOUNTS`; lỗi thì trả accounts null kèm lý do (không chứa giá trị). */
export function parseStaffAccounts(raw: string | undefined): ParsedStaffAccounts {
  if (!raw?.trim()) return { accounts: null, reason: "thiếu giá trị" };
  let json: unknown;
  try {
    json = JSON.parse(raw);
  } catch {
    return { accounts: null, reason: "không phải JSON hợp lệ" };
  }
  const result = accountsSchema.safeParse(json);
  if (!result.success) {
    return {
      accounts: null,
      reason: "sai cấu trúc [{ username, displayName, passwordHash }]",
    };
  }
  return { accounts: result.data };
}
import { AccessError } from "./access-errors";
import { signSession, STAFF_SESSION_SECONDS, verifySession } from "./session";
import { hashPassword, type StaffAccount, verifyPassword } from "./staff-accounts";

export const INVALID_CREDENTIALS_MESSAGE = "Tên đăng nhập hoặc mật khẩu không đúng";

export interface StaffIdentity {
  username: string;
  displayName: string;
}

export interface AuthServiceDeps {
  accounts: StaffAccount[];
  secret: string;
  now?: () => number;
}

let dummyHash: string | undefined;

export function createAuthService({ accounts, secret, now = Date.now }: AuthServiceDeps) {
  return {
    /** Trả về { staff, token } hoặc ném AccessError("UNAUTHENTICATED") với cùng thông báo cho mọi lỗi. */
    login(username: string, password: string): { staff: StaffIdentity; token: string } {
      const account = accounts.find((a) => a.username === username);
      // Luôn chạy một lần scrypt để thời gian phản hồi không lộ username có tồn tại hay không.
      dummyHash ??= hashPassword("dummy-password");
      const passwordOk = verifyPassword(password, account?.passwordHash ?? dummyHash);
      if (!account || !passwordOk || !secret) {
        throw new AccessError("UNAUTHENTICATED", INVALID_CREDENTIALS_MESSAGE);
      }
      const token = signSession(
        {
          username: account.username,
          exp: now() + STAFF_SESSION_SECONDS * 1000,
        },
        secret,
      );
      return {
        staff: { username: account.username, displayName: account.displayName },
        token,
      };
    },

    /** Trả về nhân viên của token hợp lệ, hoặc null. */
    readSession(token: string | undefined): StaffIdentity | null {
      if (!token) return null;
      const session = verifySession(token, secret, now());
      if (!session) return null;
      const account = accounts.find((a) => a.username === session.username);
      return account ? { username: account.username, displayName: account.displayName } : null;
    },
  };
}

export type AuthService = ReturnType<typeof createAuthService>;
