import { createAuthService } from "./auth-service";
import { parseStaffAccounts } from "./staff-accounts";

/**
 * Instance dùng chung của AuthService. Chỉ import từ code chạy trên server.
 *
 * Đọc SESSION_SECRET và STAFF_ACCOUNTS; thiếu hoặc hỏng thì ghi log tên biến
 * (không in giá trị) và từ chối mọi lần đăng nhập. Chỉ hỗ trợ một instance (AD-14).
 */
function buildAuthService() {
  const secret = process.env.SESSION_SECRET ?? "";
  const parsed = parseStaffAccounts(process.env.STAFF_ACCOUNTS);

  if (!secret) console.error("[auth] Thiếu biến môi trường SESSION_SECRET");
  if (!parsed.accounts) console.error(`[auth] STAFF_ACCOUNTS không dùng được: ${parsed.reason}`);

  if (!secret || !parsed.accounts) return createAuthService({ accounts: [], secret: "" });
  return createAuthService({ accounts: parsed.accounts, secret });
}

export const authService = buildAuthService();
import { createHmac, timingSafeEqual } from "node:crypto";

export const STAFF_COOKIE = "sl_staff";
export const STAFF_SESSION_SECONDS = 12 * 60 * 60;

export interface StaffSession {
  username: string;
  /** Thời điểm hết hạn, tính bằng mili giây epoch. */
  exp: number;
}

const sign = (data: string, secret: string) =>
  createHmac("sha256", secret).update(data).digest("base64url");

/** Tạo token dạng base64url(payload).base64url(HMAC-SHA256). */
export function signSession(session: StaffSession, secret: string): string {
  const payload = Buffer.from(JSON.stringify(session)).toString("base64url");
  return `${payload}.${sign(payload, secret)}`;
}

/** Trả về phiên nếu token đúng chữ ký, đúng định dạng và chưa hết hạn; ngược lại null. */
export function verifySession(token: string, secret: string, now: number): StaffSession | null {
  if (!secret) return null;
  const parts = token.split(".");
  if (parts.length !== 2) return null;
  const [payload, signature] = parts;

  const expected = Buffer.from(sign(payload, secret));
  const actual = Buffer.from(signature);
  if (expected.length !== actual.length || !timingSafeEqual(expected, actual)) return null;

  try {
    const data: unknown = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
    if (typeof data !== "object" || data === null) return null;
    const { username, exp } = data as Record<string, unknown>;
    if (typeof username !== "string" || !username) return null;
    if (typeof exp !== "number" || !Number.isFinite(exp) || exp <= now) return null;
    return { username, exp };
  } catch {
    return null;
  }
}
import { NextResponse } from "next/server";
import { toFieldErrors } from "@/features/checkout/checkout-schema";
import { authService } from "@/features/auth/server";
import { STAFF_COOKIE, STAFF_SESSION_SECONDS } from "@/features/auth/session";
import { loginSchema } from "@/features/auth/staff-schema";
import { handleRouteError, jsonError, readJsonBody } from "@/lib/http";

export async function POST(request: Request) {
  const body = await readJsonBody(request);
  const parsed = loginSchema.safeParse(body);
  if (!parsed.success) {
    return jsonError(400, "VALIDATION_ERROR", "Dữ liệu không hợp lệ", toFieldErrors(parsed.error));
  }

  try {
    const { staff, token } = authService.login(parsed.data.username, parsed.data.password);
    const response = NextResponse.json(staff);
    response.cookies.set(STAFF_COOKIE, token, {
      httpOnly: true,
      sameSite: "lax",
      secure: process.env.NODE_ENV === "production",
      path: "/",
      maxAge: STAFF_SESSION_SECONDS,
    });
    return response;
  } catch (error) {
    return handleRouteError(error);
  }
}
