export function safeStaffNext(next: string | null | undefined): string {
  if (!next || next.includes("\\") || /[\u0000-\u001f]/.test(next))
    return STAFF_HOME;
  if (!/^\/staff(?:[/?#]|$)/.test(next)) return STAFF_HOME;
  if (/^\/staff\/login(?:[/?#]|$)/.test(next)) return STAFF_HOME;
  return next;
}
