import { NextResponse } from "next/server";
import { orderService } from "@/features/orders/server";
import { handleRouteError, jsonError, readJsonBody } from "@/lib/http";

/** GET /api/orders/:id */
export async function GET(_request: Request, ctx: RouteContext<"/api/orders/[id]">) {
  const { id } = await ctx.params;
  try {
    return NextResponse.json(await orderService.getOrder(id));
  } catch (error) {
    return handleRouteError(error);
  }
}

/**
 * PATCH /api/orders/:id - cập nhật trạng thái đơn hàng.
 * Hiện chỉ hỗ trợ khách hàng tự hủy đơn: body { "status": "cancelled" }.
 */
export async function PATCH(request: Request, ctx: RouteContext<"/api/orders/[id]">) {
  const { id } = await ctx.params;
  const body = (await readJsonBody(request)) as { status?: unknown } | undefined;

  if (body?.status !== "cancelled") {
    return jsonError(400, "VALIDATION_ERROR", 'Chỉ hỗ trợ cập nhật { "status": "cancelled" }');
  }

  try {
    return NextResponse.json(await orderService.cancelOrder(id));
  } catch (error) {
    return handleRouteError(error);
  }
}
import { createHmac, timingSafeEqual } from "node:crypto";

export const STAFF_COOKIE = "sl_staff";
export const STAFF_SESSION_SECONDS = 12 * 60 * 60;

export interface StaffSession {
  username: string;
  /** Thời điểm hết hạn, tính bằng mili giây epoch. */
  exp: number;
}

const sign = (data: string, secret: string) =>
  createHmac("sha256", secret).update(data).digest("base64url");

/** Tạo token dạng base64url(payload).base64url(HMAC-SHA256). */
export function signSession(session: StaffSession, secret: string): string {
  const payload = Buffer.from(JSON.stringify(session)).toString("base64url");
  return `${payload}.${sign(payload, secret)}`;
}

/** Trả về phiên nếu token đúng chữ ký, đúng định dạng và chưa hết hạn; ngược lại null. */
export function verifySession(token: string, secret: string, now: number): StaffSession | null {
  if (!secret) return null;
  const parts = token.split(".");
  if (parts.length !== 2) return null;
  const [payload, signature] = parts;

  const expected = Buffer.from(sign(payload, secret));
  const actual = Buffer.from(signature);
  if (expected.length !== actual.length || !timingSafeEqual(expected, actual)) return null;

  try {
    const data: unknown = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
    if (typeof data !== "object" || data === null) return null;
    const { username, exp } = data as Record<string, unknown>;
    if (typeof username !== "string" || !username) return null;
    if (typeof exp !== "number" || !Number.isFinite(exp) || exp <= now) return null;
    return { username, exp };
  } catch {
    return null;
  }
}
import { NextResponse } from "next/server";
import { AccessError } from "@/features/auth/access-errors";
import { OrderError } from "@/features/orders/order-errors";

export interface ApiErrorBody {
  error: { code: string; message: string; details?: Record<string, string> };
}

export function jsonError(
  status: number,
  code: string,
  message: string,
  details?: Record<string, string>,
): NextResponse<ApiErrorBody> {
  return NextResponse.json({ error: { code, message, details } }, { status });
}

/** Chuyển lỗi thành response chuẩn { error: { code, message, details? } }. */
export function handleRouteError(error: unknown): NextResponse<ApiErrorBody> {
  if (error instanceof OrderError || error instanceof AccessError) {
    return jsonError(error.httpStatus, error.code, error.message, error.details);
  }
  console.error(error);
  return jsonError(500, "INTERNAL_ERROR", "Đã có lỗi xảy ra, vui lòng thử lại sau");
}

/** Đọc JSON body; trả về undefined nếu body không phải JSON hợp lệ. */
export async function readJsonBody(request: Request): Promise<unknown | undefined> {
  try {
    return await request.json();
  } catch {
    return undefined;
  }
}

import { cookies } from "next/headers";
import { AccessError } from "./access-errors";
import type { StaffIdentity } from "./auth-service";
import { authService } from "./server";
import { STAFF_COOKIE } from "./session";

/** Guard cho handler/page nhân viên: trả nhân viên hiện tại hoặc ném UNAUTHENTICATED. */
export async function requireStaff(): Promise<StaffIdentity> {
  const token = (await cookies()).get(STAFF_COOKIE)?.value;
  const staff = authService.readSession(token);
  if (!staff) throw new AccessError("UNAUTHENTICATED", "Bạn cần đăng nhập để tiếp tục");
  return staff;
}
