import { AccessError } from "./access-errors";
import { signSession, STAFF_SESSION_SECONDS, verifySession } from "./session";
import { hashPassword, type StaffAccount, verifyPassword } from "./staff-accounts";

export const INVALID_CREDENTIALS_MESSAGE = "Tên đăng nhập hoặc mật khẩu không đúng";

export interface StaffIdentity {
  username: string;
  displayName: string;
}

export interface AuthServiceDeps {
  accounts: StaffAccount[];
  secret: string;
  now?: () => number;
}

let dummyHash: string | undefined;

export function createAuthService({ accounts, secret, now = Date.now }: AuthServiceDeps) {
  return {
    /** Trả về { staff, token } hoặc ném AccessError("UNAUTHENTICATED") với cùng thông báo cho mọi lỗi. */
    login(username: string, password: string): { staff: StaffIdentity; token: string } {
      const account = accounts.find((a) => a.username === username);
      // Luôn chạy một lần scrypt để thời gian phản hồi không lộ username có tồn tại hay không.
      dummyHash ??= hashPassword("dummy-password");
      const passwordOk = verifyPassword(password, account?.passwordHash ?? dummyHash);
      if (!account || !passwordOk || !secret) {
        throw new AccessError("UNAUTHENTICATED", INVALID_CREDENTIALS_MESSAGE);
      }
      const token = signSession(
        {
          username: account.username,
          exp: now() + STAFF_SESSION_SECONDS * 1000,
        },
        secret,
      );
      return {
        staff: { username: account.username, displayName: account.displayName },
        token,
      };
    },

    /** Trả về nhân viên của token hợp lệ, hoặc null. */
    readSession(token: string | undefined): StaffIdentity | null {
      if (!token) return null;
      const session = verifySession(token, secret, now());
      if (!session) return null;
      const account = accounts.find((a) => a.username === session.username);
      return account ? { username: account.username, displayName: account.displayName } : null;
    },
  };
}

