  });

  it("lần sai cũ hơn 15 phút không còn được tính", () => {
    const limiter = createAttemptLimiter();
    for (let i = 0; i < 4; i++) limiter.recordFailure("A", "ip", T0);
    limiter.recordFailure("A", "ip", T0 + 16 * MIN);
