### Story 1.8: Khách tự hủy đơn phải được xác minh

Là khách mua hàng,
tôi muốn chỉ tôi mới hủy được đơn của mình,
để không ai biết Mã đơn mà phá được đơn của tôi.

**Yêu cầu:** FR-8 · BL-4, BL-5 · **AD liên quan:** AD-5 (giữ `cancelOrder`), AD-9, AD-10, AD-11

**Acceptance Criteria:**

**Given** người gọi chưa xác minh đơn `pending`
**When** gọi `PATCH /api/orders/<id>` với `{ "status": "cancelled" }`
**Then** trả 403 `FORBIDDEN`, đơn không đổi

**Given** người gọi đã xác minh và đơn đang `pending`
**When** gọi PATCH hủy
**Then** đơn chuyển sang `cancelled`, phản hồi là kết quả của `toCustomerOrderView`

**Given** người gọi đã xác minh nhưng đơn ở `confirmed` (hoặc bất kỳ trạng thái nào khác `pending`)
**When** gọi PATCH hủy
**Then** trả 409 `INVALID_STATUS_TRANSITION` với thông báo "Chỉ có thể hủy đơn hàng đang ở trạng thái Chờ xác nhận" (BL-4, không đổi)

**Given** body khác `{ "status": "cancelled" }`
**When** gọi PATCH
**Then** trả 400 `VALIDATION_ERROR` như hiện nay (contract giữ nguyên)

**Given** đang xem trang đơn
**When** đơn ở `pending` **và** người xem đã xác minh
**Then** mới hiện nút "Hủy đơn hàng" (`CancelOrderButton`); thiếu một trong hai điều kiện thì không hiện nút

**And** test hồi quy của `order-service.test.ts` về `cancelOrder` vẫn qua.

import { NextResponse } from "next/server";
import { isOrderVerified } from "@/features/auth/guards";
import { toCustomerOrderView } from "@/features/orders/customer-view";
import { orderService } from "@/features/orders/server";
import { handleRouteError, jsonError, readJsonBody } from "@/lib/http";

/** GET /api/orders/:id */
export async function GET(
  _request: Request,
  ctx: RouteContext<"/api/orders/[id]">,
) {
  const { id } = await ctx.params;
  try {
    const order = await orderService.getOrder(id);
    return NextResponse.json(
      toCustomerOrderView(order, { verified: await isOrderVerified(id) }),
    );
  } catch (error) {
    return handleRouteError(error);
  }
}

/**
 * PATCH /api/orders/:id - cập nhật trạng thái đơn hàng.
 * Hiện chỉ hỗ trợ khách hàng tự hủy đơn: body { "status": "cancelled" }.
 */
export async function PATCH(
  request: Request,
  ctx: RouteContext<"/api/orders/[id]">,
) {
  const { id } = await ctx.params;
  const body = (await readJsonBody(request)) as
    { status?: unknown } | undefined;

  if (body?.status !== "cancelled") {
    return jsonError(
      400,
      "VALIDATION_ERROR",
      'Chỉ hỗ trợ cập nhật { "status": "cancelled" }',
    );
  }

  try {
    const order = await orderService.cancelOrder(id);
    return NextResponse.json(
      toCustomerOrderView(order, { verified: await isOrderVerified(id) }),
    );
  } catch (error) {
    return handleRouteError(error);
  }
}
import { cookies } from "next/headers";
import type { NextResponse } from "next/server";
import { AccessError } from "./access-errors";
import type { StaffIdentity } from "./auth-service";
import { authService } from "./server";
import { ORDERS_COOKIE, ORDERS_COOKIE_SECONDS, STAFF_COOKIE } from "./session";

/** Guard cho handler/page nhân viên: trả nhân viên hiện tại hoặc ném UNAUTHENTICATED. */
export async function requireStaff(): Promise<StaffIdentity> {
  const token = (await cookies()).get(STAFF_COOKIE)?.value;
  const staff = authService.readSession(token);
  if (!staff)
    throw new AccessError("UNAUTHENTICATED", "Bạn cần đăng nhập để tiếp tục");
  return staff;
}

/** Thiết bị này đã đặt (hoặc đã xác minh) đơn `orderId` hay chưa. Cookie hỏng thì coi là chưa. */
export async function isOrderVerified(orderId: string): Promise<boolean> {
  const token = (await cookies()).get(ORDERS_COOKIE)?.value;
  return authService.readVerifiedOrders(token).includes(orderId);
}

/** Các Mã đơn thiết bị này đã đặt/xác minh (đã ký). Cookie hỏng thì rỗng. */
export async function verifiedOrderIds(): Promise<string[]> {
  const token = (await cookies()).get(ORDERS_COOKIE)?.value;
  return authService.readVerifiedOrders(token);
}

/** Gắn cookie `sl_orders` (đã thêm `orderId`) vào response. Không làm gì nếu thiếu SESSION_SECRET. */
export async function rememberOrder(
  response: { cookies: Pick<NextResponse["cookies"], "set"> },
  orderId: string,
): Promise<void> {
  const current = (await cookies()).get(ORDERS_COOKIE)?.value;
  const token = authService.addVerifiedOrder(current, orderId);
  if (!token) return;
  response.cookies.set(ORDERS_COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: ORDERS_COOKIE_SECONDS,
  });
}
