import type { CartItem } from "@/features/cart/types";
import { formatCurrency } from "@/lib/format";

interface CartItemRowProps {
  item: CartItem;
  onQuantityChange: (quantity: number) => void;
  onRemove: () => void;
}

export function CartItemRow({ item, onQuantityChange, onRemove }: CartItemRowProps) {
  return (
    <li className="flex gap-4 py-4" data-testid="cart-item">
      <Link href={`/products/${item.slug}`} className="w-20 shrink-0 sm:w-24">
        <ProductImage image={item.image} alt={item.name} size="sm" />
      </Link>
      <div className="flex flex-1 flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <Link
            href={`/products/${item.slug}`}
            className="font-semibold text-slate-900 hover:text-indigo-600"
          >
            {item.name}
          </Link>
          <p className="text-sm text-slate-500">{formatCurrency(item.price)}</p>
        </div>
        <div className="flex items-center gap-4">
          <QuantityInput
            value={item.quantity}
            max={getMaxQuantity(item.stock)}
            onChange={onQuantityChange}
            label={`Số lượng ${item.name}`}
          />
          <p className="w-28 text-right font-semibold text-slate-900">
            {formatCurrency(item.price * item.quantity)}
          </p>
          <button
            type="button"
            onClick={onRemove}
            aria-label={`Xóa ${item.name} khỏi giỏ hàng`}
            className="rounded-lg p-2 text-slate-400 hover:bg-rose-50 hover:text-rose-600"
          >
            <Trash2 className="size-4" />
          </button>
        </div>
      </div>
    </li>
  );
}
import Link from "next/link";
import { Truck } from "lucide-react";
import { buttonStyles } from "@/components/ui/button";
import {
  amountUntilFreeShipping,
  calculateShippingFee,
  FREE_SHIPPING_THRESHOLD,
} from "@/features/checkout/pricing";
import { formatCurrency } from "@/lib/format";

export function CartSummary({ subtotal }: { subtotal: number }) {
  const shippingFee = calculateShippingFee(subtotal, "standard");
  const remaining = amountUntilFreeShipping(subtotal);
  const progress = Math.min(100, Math.round((subtotal / FREE_SHIPPING_THRESHOLD) * 100));

  return (
    <aside className="flex flex-col gap-4 rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200">
      <h2 className="text-lg font-semibold">Tóm tắt đơn hàng</h2>

      <div className="rounded-xl bg-indigo-50 p-3 text-sm text-indigo-900">
        <p className="flex items-center gap-2 font-medium">
          <Truck className="size-4" />
          {remaining > 0
            ? `Mua thêm ${formatCurrency(remaining)} để được miễn phí giao hàng`
            : "Đơn hàng của bạn được miễn phí giao hàng tiêu chuẩn 🎉"}
        </p>
        <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-indigo-100">
          <div className="h-full rounded-full bg-indigo-600" style={{ width: `${progress}%` }} />
        </div>
      </div>

      <dl className="flex flex-col gap-2 text-sm">
        <div className="flex justify-between">
          <dt className="text-slate-600">Tạm tính</dt>
          <dd className="font-medium">{formatCurrency(subtotal)}</dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-slate-600">Phí giao hàng (tiêu chuẩn)</dt>
          <dd className="font-medium">
            {shippingFee === 0 ? "Miễn phí" : formatCurrency(shippingFee)}
          </dd>
        </div>
        <div className="flex justify-between border-t border-slate-200 pt-3 text-base">
          <dt className="font-semibold">Tổng cộng</dt>
          <dd className="font-bold text-indigo-700" data-testid="cart-total">
            {formatCurrency(subtotal + shippingFee)}
          </dd>
        </div>
      </dl>

      <Link href="/checkout" className={buttonStyles({ size: "lg", className: "w-full" })}>
        Tiến hành thanh toán
      </Link>
      <Link
        href="/products"
        className="text-center text-sm font-medium text-indigo-600 hover:underline"
      >
        Tiếp tục mua sắm
      </Link>
    </aside>
  );
}
import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { beforeEach, describe, expect, it } from "vitest";
import { getProductById } from "@/features/catalog/catalog-service";
import { toCartItem } from "@/features/cart/cart-reducer";
import { cartStore } from "@/features/cart/cart-store";
import { CartView } from "./cart-view";

function seedCart(entries: [productId: string, quantity: number][]) {
  for (const [productId, quantity] of entries) {
    cartStore.dispatch({ type: "add", item: toCartItem(getProductById(productId)!), quantity });
  }
}

describe("<CartView />", () => {
  beforeEach(() => cartStore.reset());

  it("hiển thị trạng thái giỏ hàng trống", () => {
    render(<CartView />);
    expect(screen.getByText("Giỏ hàng của bạn đang trống")).toBeVisible();
  });

  it("hiển thị gợi ý mua thêm để được miễn phí giao hàng", () => {
    seedCart([["p010", 1]]); // 150.000đ
    render(<CartView />);

    expect(screen.getAllByTestId("cart-item")).toHaveLength(1);
    expect(screen.getByText(/Mua thêm 350\.000/)).toBeVisible();
    expect(screen.getByTestId("cart-total")).toHaveTextContent(/180\.000/);
  });

  it("cập nhật số lượng và tổng tiền", async () => {
    const user = userEvent.setup();
    seedCart([["p010", 1]]);
    render(<CartView />);

    const row = screen.getByTestId("cart-item");
    await user.click(within(row).getByRole("button", { name: "Tăng số lượng" }));

    expect(within(row).getByRole("spinbutton")).toHaveValue(2);
    expect(screen.getByTestId("cart-total")).toHaveTextContent(/330\.000/);
  });

  it("xóa sản phẩm khỏi giỏ", async () => {
    const user = userEvent.setup();
    seedCart([
      ["p010", 1],
      ["p006", 1],
    ]);
    render(<CartView />);

    await user.click(screen.getByRole("button", { name: /Xóa Cáp USB-C/ }));

    expect(screen.getAllByTestId("cart-item")).toHaveLength(1);
    expect(screen.queryByText("Cáp USB-C bện dù 2m")).not.toBeInTheDocument();
  });
});
"use client";

import Link from "next/link";
import { buttonStyles } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { useCart } from "@/features/cart/use-cart";
import { CartItemRow } from "./cart-item-row";
import { CartSummary } from "./cart-summary";

export function CartView() {
  const { items, itemCount, subtotal, hydrated, updateQuantity, removeItem, clear } = useCart();

  if (!hydrated) {
    return <div className="h-64 animate-pulse rounded-2xl bg-slate-200/60" aria-busy />;
  }

  if (items.length === 0) {
    return (
      <EmptyState
        emoji="🛒"
        title="Giỏ hàng của bạn đang trống"
        description="Hãy khám phá các sản phẩm công nghệ đang được ưa chuộng nhất."
        action={
          <Link href="/products" className={buttonStyles()}>
            Mua sắm ngay
          </Link>
        }
      />
    );
  }

  return (
    <div className="grid gap-6 lg:grid-cols-[1fr_360px]">
      <section className="rounded-2xl bg-white px-5 shadow-sm ring-1 ring-slate-200">
        <div className="flex items-center justify-between border-b border-slate-100 py-4">
          <p className="text-sm text-slate-600">{itemCount} sản phẩm</p>
          <button
            type="button"
            onClick={clear}
            className="text-sm font-medium text-rose-600 hover:underline"
          >
            Xóa tất cả
          </button>
        </div>
        <ul className="divide-y divide-slate-100">
          {items.map((item) => (
            <CartItemRow
              key={item.productId}
              item={item}
              onQuantityChange={(quantity) => updateQuantity(item.productId, quantity)}
              onRemove={() => removeItem(item.productId)}
            />
          ))}
        </ul>
      </section>
      <CartSummary subtotal={subtotal} />
    </div>
  );
}
"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import { Zap } from "lucide-react";
import { Button } from "@/components/ui/button";
import { QuantityInput } from "@/components/ui/quantity-input";
import type { Product } from "@/features/catalog/types";
import { getMaxQuantity } from "@/features/cart/cart-reducer";
import { getQuantityInCart, useCart } from "@/features/cart/use-cart";
import { AddToCartButton } from "./add-to-cart-button";

/** Khối chọn số lượng + "Thêm vào giỏ" + "Mua ngay" ở trang chi tiết sản phẩm. */
export function ProductPurchasePanel({ product }: { product: Product }) {
  const router = useRouter();
  const { items, addItem } = useCart();
  const [quantity, setQuantity] = useState(1);

  const remaining = getMaxQuantity(product.stock) - getQuantityInCart(items, product.id);
  // Không cho chọn vượt quá số lượng còn có thể thêm vào giỏ.
  const selectedQuantity = Math.min(quantity, Math.max(1, remaining));

  if (product.stock <= 0) {
    return (
      <p className="rounded-xl bg-slate-100 px-4 py-3 text-sm text-slate-600">
        Sản phẩm tạm hết hàng. Vui lòng quay lại sau.
      </p>
    );
  }

  function handleBuyNow() {
    addItem(product, selectedQuantity);
    router.push("/checkout");
  }

  return (
    <div className="flex flex-col gap-3" data-testid="purchase-panel">
      <div className="flex items-center gap-3">
        <QuantityInput
          value={selectedQuantity}
          max={Math.max(1, remaining)}
          onChange={setQuantity}
        />
        {remaining <= 0 && (
          <span className="text-sm text-amber-700">
            Bạn đã có số lượng tối đa của sản phẩm này trong giỏ.
          </span>
        )}
      </div>
      <div className="flex flex-wrap gap-3">
        <AddToCartButton
          product={product}
          quantity={selectedQuantity}
          size="lg"
          className="flex-1"
        />
        <Button
          size="lg"
          variant="secondary"
          onClick={handleBuyNow}
          disabled={remaining <= 0}
          className="flex-1"
        >
          <Zap className="size-4" />
          Mua ngay
        </Button>
      </div>
    </div>
  );
}
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { getProductById } from "@/features/catalog/catalog-service";
import { toCartItem } from "@/features/cart/cart-reducer";
import { cartStore } from "@/features/cart/cart-store";
import { CheckoutForm } from "./checkout-form";

const push = vi.fn();
vi.mock("next/navigation", () => ({ useRouter: () => ({ push, refresh: vi.fn() }) }));

describe("<CheckoutForm />", () => {
  beforeEach(() => {
    cartStore.reset();
    cartStore.dispatch({ type: "add", item: toCartItem(getProductById("p010")!), quantity: 2 });
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    push.mockReset();
  });

  it("hiển thị lỗi validate khi gửi form trống và không gọi API", async () => {
    const fetchMock = vi.fn();
    vi.stubGlobal("fetch", fetchMock);
    const user = userEvent.setup();
    render(<CheckoutForm />);

    await user.click(screen.getByRole("button", { name: "Đặt hàng" }));

    expect(screen.getByTestId("error-fullName")).toBeVisible();
    expect(screen.getByTestId("error-phone")).toHaveTextContent(/Số điện thoại không hợp lệ/);
    expect(screen.getByTestId("error-address")).toBeVisible();
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it("cập nhật phí giao hàng khi đổi phương thức giao hàng", async () => {
    const user = userEvent.setup();
    render(<CheckoutForm />);

    expect(screen.getByTestId("shipping-fee")).toHaveTextContent(/30\.000/);
    await user.click(screen.getByText("Giao hàng nhanh"));
    expect(screen.getByTestId("shipping-fee")).toHaveTextContent(/60\.000/);
  });

  it("gửi đơn hàng, xóa giỏ và chuyển tới trang đơn hàng", async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValue(
        new Response(JSON.stringify({ id: "SL-20261021-ABC123" }), { status: 201 }),
      );
    vi.stubGlobal("fetch", fetchMock);
    const user = userEvent.setup();
    render(<CheckoutForm />);

    await user.type(screen.getByLabelText(/Họ và tên/), "Nguyễn Văn A");
    await user.type(screen.getByLabelText(/Số điện thoại/), "0912345678");
    await user.type(screen.getByLabelText(/Địa chỉ giao hàng/), "12 Nguyễn Huệ, Quận 1, TP.HCM");
    await user.click(screen.getByRole("button", { name: "Đặt hàng" }));

    const [url, init] = fetchMock.mock.calls[0];
    expect(url).toBe("/api/orders");
    expect(JSON.parse(init.body)).toMatchObject({
      shippingMethod: "standard",
      paymentMethod: "cod",
      items: [{ productId: "p010", quantity: 2 }],
      customer: { fullName: "Nguyễn Văn A", phone: "0912345678" },
    });
    expect(push).toHaveBeenCalledWith("/orders/SL-20261021-ABC123?placed=1");
    expect(cartStore.getSnapshot().items).toEqual([]);
  });

  it("hiển thị thông báo lỗi từ server", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn().mockResolvedValue(
        new Response(
          JSON.stringify({
            error: { code: "INSUFFICIENT_STOCK", message: "Sản phẩm đã hết hàng" },
          }),
          { status: 409 },
        ),
      ),
    );
    const user = userEvent.setup();
    render(<CheckoutForm />);

    await user.type(screen.getByLabelText(/Họ và tên/), "Nguyễn Văn A");
    await user.type(screen.getByLabelText(/Số điện thoại/), "0912345678");
    await user.type(screen.getByLabelText(/Địa chỉ giao hàng/), "12 Nguyễn Huệ, Quận 1, TP.HCM");
    await user.click(screen.getByRole("button", { name: "Đặt hàng" }));

    expect(await screen.findByRole("alert")).toHaveTextContent("Sản phẩm đã hết hàng");
    expect(push).not.toHaveBeenCalled();
  });
});
"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState, type ChangeEvent, type FormEvent, type ReactNode } from "react";
import { Banknote, CreditCard, Truck, Zap } from "lucide-react";
import { Button, buttonStyles } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { Field, inputClass } from "@/components/ui/field";
import { useCart } from "@/features/cart/use-cart";
import {
  checkoutFormSchema,
  PAYMENT_METHODS,
  PAYMENT_OPTIONS,
  toFieldErrors,
  type CheckoutFormValues,
  type PaymentMethod,
} from "@/features/checkout/checkout-schema";
import {
  calculateShippingFee,
  SHIPPING_METHODS,
  SHIPPING_OPTIONS,
  type ShippingMethod,
} from "@/features/checkout/pricing";
import type { ApiErrorBody } from "@/lib/http";
import type { Order } from "@/features/orders/types";
import { cn } from "@/lib/cn";
import { formatCurrency } from "@/lib/format";
import { CheckoutSummary } from "./checkout-summary";

const INITIAL_VALUES: CheckoutFormValues = {
  fullName: "",
  phone: "",
  email: "",
  address: "",
  note: "",
  shippingMethod: "standard",
  paymentMethod: "cod",
};

const SHIPPING_ICONS: Record<ShippingMethod, ReactNode> = {
  standard: <Truck className="size-5" />,
  express: <Zap className="size-5" />,
};

const PAYMENT_ICONS: Record<PaymentMethod, ReactNode> = {
  cod: <Banknote className="size-5" />,
  bank_transfer: <CreditCard className="size-5" />,
};

export function CheckoutForm() {
  const router = useRouter();
  const { items, subtotal, hydrated, clear } = useCart();
  const [values, setValues] = useState<CheckoutFormValues>(INITIAL_VALUES);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [status, setStatus] = useState<"idle" | "submitting" | "redirecting">("idle");

  if (!hydrated) {
    return <div className="h-96 animate-pulse rounded-2xl bg-slate-200/60" aria-busy />;
  }

  if (status === "redirecting") {
    return (
      <p className="py-16 text-center text-slate-600">Đặt hàng thành công, đang chuyển trang…</p>
    );
  }

  if (items.length === 0) {
    return (
      <EmptyState
        emoji="🧾"
        title="Chưa có sản phẩm để thanh toán"
        description="Giỏ hàng của bạn đang trống."
        action={
          <Link href="/products" className={buttonStyles()}>
            Xem sản phẩm
          </Link>
        }
      />
    );
  }

  function handleChange(event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) {
    const { name, value } = event.target;
    setValues((current) => ({ ...current, [name]: value }));
    setErrors((current) => {
      if (!current[name]) return current;
      const next = { ...current };
      delete next[name];
      return next;
    });
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitError(null);

    const parsed = checkoutFormSchema.safeParse(values);
    if (!parsed.success) {
      setErrors(toFieldErrors(parsed.error));
      return;
    }

    const { shippingMethod, paymentMethod, ...customer } = parsed.data;
    setStatus("submitting");

    try {
      const response = await fetch("/api/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          customer,
          shippingMethod,
          paymentMethod,
          items: items.map((item) => ({ productId: item.productId, quantity: item.quantity })),
        }),
      });

      if (!response.ok) {
        const body = (await response.json().catch(() => null)) as ApiErrorBody | null;
        setSubmitError(body?.error.message ?? "Không thể đặt hàng, vui lòng thử lại.");
        setStatus("idle");
        return;
      }

      const order = (await response.json()) as Order;
      setStatus("redirecting");
      clear();
      router.push(`/orders/${order.id}?placed=1`);
    } catch {
      setSubmitError("Không kết nối được máy chủ, vui lòng thử lại.");
      setStatus("idle");
    }
  }

  return (
    <form onSubmit={handleSubmit} noValidate className="grid gap-6 lg:grid-cols-[1fr_380px]">
      <div className="flex flex-col gap-6">
        <section className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200">
          <h2 className="mb-4 text-lg font-semibold">Thông tin nhận hàng</h2>
          <div className="grid gap-4 sm:grid-cols-2">
            <Field label="Họ và tên" name="fullName" error={errors.fullName} required>
              <input
                id="fullName"
                name="fullName"
                value={values.fullName}
                onChange={handleChange}
                autoComplete="name"
                placeholder="Nguyễn Văn A"
                aria-invalid={Boolean(errors.fullName)}
                className={cn(inputClass, errors.fullName ? "ring-rose-400" : "ring-slate-300")}
              />
            </Field>
            <Field label="Số điện thoại" name="phone" error={errors.phone} required>
              <input
                id="phone"
                name="phone"
                type="tel"
                value={values.phone}
                onChange={handleChange}
                autoComplete="tel"
                placeholder="0912345678"
                aria-invalid={Boolean(errors.phone)}
                className={cn(inputClass, errors.phone ? "ring-rose-400" : "ring-slate-300")}
              />
            </Field>
            <Field label="Email" name="email" error={errors.email} className="sm:col-span-2">
              <input
                id="email"
                name="email"
                type="email"
                value={values.email}
                onChange={handleChange}
                autoComplete="email"
                placeholder="ban@example.com (không bắt buộc)"
                aria-invalid={Boolean(errors.email)}
                className={cn(inputClass, errors.email ? "ring-rose-400" : "ring-slate-300")}
              />
            </Field>
            <Field
              label="Địa chỉ giao hàng"
              name="address"
              error={errors.address}
              required
              className="sm:col-span-2"
            >
              <input
                id="address"
                name="address"
                value={values.address}
                onChange={handleChange}
                autoComplete="street-address"
                placeholder="Số nhà, đường, phường/xã, quận/huyện, tỉnh/thành"
                aria-invalid={Boolean(errors.address)}
                className={cn(inputClass, errors.address ? "ring-rose-400" : "ring-slate-300")}
              />
            </Field>
            <Field label="Ghi chú" name="note" error={errors.note} className="sm:col-span-2">
              <textarea
                id="note"
                name="note"
                rows={2}
                value={values.note}
                onChange={handleChange}
                placeholder="Ví dụ: giao giờ hành chính"
                className={cn(
                  inputClass,
                  "h-auto py-2",
                  errors.note ? "ring-rose-400" : "ring-slate-300",
                )}
              />
            </Field>
          </div>
        </section>

        <section className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200">
          <h2 className="mb-4 text-lg font-semibold">Phương thức giao hàng</h2>
          <div className="grid gap-3 sm:grid-cols-2">
            {SHIPPING_METHODS.map((method) => {
              const fee = calculateShippingFee(subtotal, method);
              return (
                <OptionCard
                  key={method}
                  name="shippingMethod"
                  value={method}
                  checked={values.shippingMethod === method}
                  onChange={() => setValues((current) => ({ ...current, shippingMethod: method }))}
                  icon={SHIPPING_ICONS[method]}
                  title={SHIPPING_OPTIONS[method].label}
                  description={`${SHIPPING_OPTIONS[method].description} · ${fee === 0 ? "Miễn phí" : formatCurrency(fee)}`}
                />
              );
            })}
          </div>
        </section>

        <section className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200">
          <h2 className="mb-4 text-lg font-semibold">Phương thức thanh toán</h2>
          <div className="grid gap-3 sm:grid-cols-2">
            {PAYMENT_METHODS.map((method) => (
              <OptionCard
                key={method}
                name="paymentMethod"
                value={method}
                checked={values.paymentMethod === method}
                onChange={() => setValues((current) => ({ ...current, paymentMethod: method }))}
                icon={PAYMENT_ICONS[method]}
                title={PAYMENT_OPTIONS[method].label}
                description={PAYMENT_OPTIONS[method].description}
              />
            ))}
          </div>
        </section>
      </div>

      <div className="flex flex-col gap-4">
