import { getProductById } from "@/features/catalog/catalog-service";
import type { Product } from "@/features/catalog/types";
import { placeOrderSchema, toFieldErrors } from "@/features/checkout/checkout-schema";
import { calculateOrderTotals } from "@/features/checkout/pricing";
import { OrderError } from "./order-errors";
import type { OrderRepository } from "./order-repository";
import { matchesStatusFilter, QUEUE_CHIPS, type StatusFilter } from "./staff-order-schema";
import type { Order, OrderItem } from "./types";

/** Chuẩn hóa ô tìm mã đơn: bỏ khoảng trắng, viết hoa. "4f9a2c " -> "4F9A2C" */
export function normalizeOrderCode(value: string): string {
  return value.replace(/\s+/g, "").toUpperCase();
}

const SHORT_CODE_LENGTH = 6;

export interface OrderServiceDeps {
  repository: OrderRepository;
  findProduct?: (id: string) => Product | undefined;
  now?: () => Date;
  generateId?: (date: Date) => string;
}

/** Mã đơn hàng dạng SL-20261021-4F9A2C */
export function generateOrderId(date: Date): string {
  const ymd = date.toISOString().slice(0, 10).replace(/-/g, "");
  const random = crypto.randomUUID().replace(/-/g, "").slice(0, 6).toUpperCase();
  return `SL-${ymd}-${random}`;
}

/** Gộp các dòng trùng productId: [{p1, 2}, {p1, 1}] -> [{p1, 3}] */
function mergeItems(items: { productId: string; quantity: number }[]) {
  const merged = new Map<string, number>();
  for (const item of items) {
    merged.set(item.productId, (merged.get(item.productId) ?? 0) + item.quantity);
  }
  return [...merged.entries()].map(([productId, quantity]) => ({ productId, quantity }));
}

export function createOrderService({
  repository,
  findProduct = getProductById,
  now = () => new Date(),
  generateId = generateOrderId,
}: OrderServiceDeps) {
  async function getOrder(id: string): Promise<Order> {
    const order = await repository.findById(id);
    if (!order) {
      throw new OrderError("ORDER_NOT_FOUND", `Không tìm thấy đơn hàng "${id}"`);
    }
    return order;
  }

  return {
    /**
     * Tạo đơn hàng mới từ payload của client.
     * - Validate dữ liệu bằng placeOrderSchema
     * - Lấy giá từ catalog (bỏ qua mọi giá client gửi lên)
     * - Kiểm tra tồn kho
     */
    async placeOrder(input: unknown): Promise<Order> {
      const parsed = placeOrderSchema.safeParse(input);
      if (!parsed.success) {
        throw new OrderError(
          "VALIDATION_ERROR",
          "Thông tin đơn hàng không hợp lệ",
          toFieldErrors(parsed.error),
        );
      }

      const { customer, items, shippingMethod, paymentMethod } = parsed.data;

      const orderItems: OrderItem[] = mergeItems(items).map(({ productId, quantity }) => {
        const product = findProduct(productId);
        if (!product) {
          throw new OrderError("PRODUCT_NOT_FOUND", `Không tìm thấy sản phẩm "${productId}"`);
        }
        if (quantity > product.stock) {
          throw new OrderError(
            "INSUFFICIENT_STOCK",
            product.stock === 0
              ? `Sản phẩm "${product.name}" đã hết hàng`
              : `Sản phẩm "${product.name}" chỉ còn ${product.stock} sản phẩm`,
          );
        }
        return {
          productId: product.id,
          slug: product.slug,
          name: product.name,
          image: product.image,
          unitPrice: product.price,
          quantity,
          lineTotal: product.price * quantity,
        };
      });

      const createdAt = now();
      const order: Order = {
        id: generateId(createdAt),
        status: "pending",
        createdAt: createdAt.toISOString(),
        updatedAt: createdAt.toISOString(),
        customer: {
          fullName: customer.fullName,
          phone: customer.phone,
          email: customer.email || undefined,
          address: customer.address,
          note: customer.note || undefined,
        },
        shippingMethod,
        paymentMethod,
        items: orderItems,
        ...calculateOrderTotals(orderItems, shippingMethod),
      };

      await repository.save(order);
      return order;
    },

    /**
     * Danh sách đơn hàng, có thể lọc theo trạng thái.
     * Riêng "pending" xếp cũ nhất trước (đơn chờ lâu nhất lên đầu); còn lại mới nhất trước.
     */
    async listOrders({ status }: { status?: StatusFilter } = {}): Promise<Order[]> {
      const all = await repository.findAll();
      const orders = status ? all.filter((o) => matchesStatusFilter(o.status, status)) : all;
      const oldestFirst = status === "pending";
      return orders.sort((a, b) =>
        oldestFirst ? a.createdAt.localeCompare(b.createdAt) : b.createdAt.localeCompare(a.createdAt),
      );
    },

    /** Tìm theo Mã đơn đầy đủ (khớp chính xác) hoặc 6 ký tự cuối, ở mọi trạng thái. */
    async searchOrders(query: string): Promise<Order[]> {
      const code = normalizeOrderCode(query);
      if (!code) return [];
      const all = await repository.findAll();
      return all
        .filter(
          (o) =>
            o.id.toUpperCase() === code ||
            (code.length === SHORT_CODE_LENGTH && o.id.toUpperCase().endsWith(code)),
        )
        .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    },

    /** Số đơn của từng chip bộ lọc, tính trong một lần đọc. */
    async countByFilter(): Promise<Record<string, number>> {
      const all = await repository.findAll();
      const counts: Record<string, number> = {};
      for (const { filter } of QUEUE_CHIPS) {
        counts[filter] = all.filter((o) => matchesStatusFilter(o.status, filter)).length;
      }
      return counts;
    },

    getOrder,

    /** Khách hàng chỉ được hủy đơn khi đơn còn ở trạng thái "Chờ xác nhận". */
    async cancelOrder(id: string): Promise<Order> {
      const order = await getOrder(id);
      if (order.status !== "pending") {
        throw new OrderError(
          "INVALID_STATUS_TRANSITION",
          "Chỉ có thể hủy đơn hàng đang ở trạng thái Chờ xác nhận",
        );
      }
      const cancelled: Order = { ...order, status: "cancelled", updatedAt: now().toISOString() };
      await repository.save(cancelled);
      return cancelled;
    },
  };
}

export type OrderService = ReturnType<typeof createOrderService>;
export type OrderErrorCode =
  | "VALIDATION_ERROR"
  | "PRODUCT_NOT_FOUND"
  | "INSUFFICIENT_STOCK"
  | "ORDER_NOT_FOUND"
  | "INVALID_STATUS_TRANSITION";

const HTTP_STATUS_BY_CODE: Record<OrderErrorCode, number> = {
  VALIDATION_ERROR: 400,
  PRODUCT_NOT_FOUND: 422,
  INSUFFICIENT_STOCK: 409,
  ORDER_NOT_FOUND: 404,
  INVALID_STATUS_TRANSITION: 409,
};

/** Lỗi nghiệp vụ của đơn hàng - route handler chuyển thành HTTP response tương ứng. */
export class OrderError extends Error {
  readonly code: OrderErrorCode;
  readonly details?: Record<string, string>;

  constructor(code: OrderErrorCode, message: string, details?: Record<string, string>) {
    super(message);
    this.name = "OrderError";
    this.code = code;
    this.details = details;
  }

  get httpStatus(): number {
    return HTTP_STATUS_BY_CODE[this.code];
  }
}
